// Builds rust/stm-core to WebAssembly and writes src/rust/stm-core.wasm.js (the bytes as base64 and the hash of the
// Rust sources). The generated file is committed: tests, the app and the packaged build need no Rust toolchain.
// Usage: node scripts/build-rust.mjs [--test]   (--test also runs cargo fmt --check, clippy and cargo test first)
import {spawnSync} from 'node:child_process';
import {existsSync,mkdirSync,readFileSync,writeFileSync} from 'node:fs';
import path from 'node:path';
import {RUST_ROOT,rustSourceHash} from './rust-source-hash.mjs';

const crate=path.join(RUST_ROOT,'stm-core'),output=path.join(RUST_ROOT,'..','src','rust','stm-core.wasm.js');
// cargo from PATH, or from the per-user install this project uses on Windows (not on the system PATH).
const local=process.env.LOCALAPPDATA?path.join(process.env.LOCALAPPDATA,'Programs','rust'):null,env={...process.env};
if(local&&existsSync(path.join(local,'cargo','bin'))&&!process.env.CARGO_HOME){
 env.CARGO_HOME=path.join(local,'cargo');env.RUSTUP_HOME=path.join(local,'rustup');env.PATH=path.join(local,'cargo','bin')+path.delimiter+env.PATH;
}
// The same bytes whatever folder the sources are in.
env.RUSTFLAGS=`${env.RUSTFLAGS||''} --remap-path-prefix=${crate}=stm-core --remap-path-prefix=${env.CARGO_HOME||path.join(process.env.USERPROFILE||process.env.HOME||'','.cargo')}=cargo`.trim();
const cargo=(...args)=>{
 const r=spawnSync('cargo',args,{cwd:crate,env,stdio:'inherit'});
 if(r.error)throw new Error(`cargo를 실행할 수 없습니다(${r.error.message}). Rust(rustup)를 설치하세요.`);
 if(r.status!==0)process.exit(r.status??1);
};
if(process.argv.includes('--test')){cargo('fmt','--check');cargo('clippy','--all-targets','--locked','--','-D','warnings');cargo('test','--locked');}
cargo('build','--release','--locked','--target','wasm32-unknown-unknown');
const wasm=readFileSync(path.join(crate,'target','wasm32-unknown-unknown','release','stm_core.wasm'));
mkdirSync(path.dirname(output),{recursive:true});
writeFileSync(output,`// Generated by scripts/build-rust.mjs from rust/stm-core — do not edit. Rebuild with: npm run build:rust
export const SOURCE_HASH='${rustSourceHash()}';
export const WASM_BASE64='${wasm.toString('base64')}';
`);
console.log(`src/rust/stm-core.wasm.js: ${wasm.length} bytes of WebAssembly`);
